import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { getCurrentLanguage } from '../config/languageConfig';

const SearchBar: React.FC = () => {
  const navigate = useNavigate();
  const [searchTerm, setSearchTerm] = useState('');
  const [isFocused, setIsFocused] = useState(false);
  const [currentFoodIndex, setCurrentFoodIndex] = useState(0);
  const currentLang = getCurrentLanguage();

  // 언어별 음식 이름들
  const getFoodItemsByLanguage = () => {
    const foodItems = {
      'en': ['Chicken', 'Tteokbokki', 'Bibimbap', 'Bulgogi', 'Samgyeopsal', 'Jjajang'],
      'ko': ['치킨', '떡볶이', '비빔밥', '불고기', '삼겹살', '짜장면'],
      'ja': ['チキン', 'トッポッキ', 'ビビンバ', 'プルコギ', 'サムギョプサル', 'ジャージャー麺'],
      'zh-CN': ['炸鸡', '年糕', '拌饭', '烤肉', '五花肉', '炸酱面'],
      'zh-TW': ['炸雞', '年糕', '拌飯', '烤肉', '五花肉', '炸醬麵']
    };
    return foodItems[currentLang] || foodItems['en'];
  };

  // 언어별 "Search for" 텍스트
  const getSearchText = () => {
    const searchTexts = {
      'en': 'Search for',
      'ko': '검색하기',
      'ja': '検索する',
      'zh-CN': '搜索',
      'zh-TW': '搜尋'
    };
    return searchTexts[currentLang] || searchTexts['en'];
  };

  const foodItems = getFoodItemsByLanguage();

  // 플레이스홀더 롤링 효과
  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentFoodIndex((prevIndex) => (prevIndex + 1) % foodItems.length);
    }, 2000); // 2초마다 변경

    return () => clearInterval(interval);
  }, [foodItems.length]);

  // 동적 플레이스홀더 생성
  const getDynamicPlaceholder = () => {
    return `${getSearchText()} "${foodItems[currentFoodIndex]}"`;
  };

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    if (searchTerm.trim()) {
      // 검색 결과 페이지로 이동
      const params = new URLSearchParams({
        menuName: searchTerm.trim(),
        searchType: 'menu',
        lang: currentLang  // 현재 언어 추가
      });
      navigate(`/search-results?${params.toString()}`);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSearchTerm(e.target.value);
  };

  // 입력 필드 클릭 시 검색 지면으로 이동
  const handleInputClick = () => {
    navigate('/search');
  };

  const handleFocus = () => {
    setIsFocused(true);
    // onClick에서 이미 navigate 하므로 여기서는 제거
  };

  const handleBlur = () => {
    setIsFocused(false);
  };

  const handleClear = () => {
    setSearchTerm('');
  };

  return (
    <div className="px-2.5 pb-1.5 pt-2 md-background">
      <form onSubmit={handleSearch} className="relative" role="search">
        <div className="relative">
          <input
            type="text"
            value={searchTerm}
            onChange={handleInputChange}
            onFocus={handleFocus}
            onBlur={handleBlur}
            onClick={handleInputClick}
            placeholder={getDynamicPlaceholder()}
            aria-label="Search restaurants and food"
            aria-describedby="search-description"
            className={`w-full px-4 py-2 pl-12 pr-12 bg-white rounded-2xl transition-all duration-300 ease-out md-body-large md-on-surface placeholder:md-on-surface-variant relative outline-none focus:outline-none ${
              isFocused 
                ? 'ring-2 ring-[#dc2626] border-transparent elevation-3 bg-red-50' 
                : 'border border-gray-200 elevation-1 hover:elevation-2 hover:bg-gray-50 active:bg-gray-100'
            }`}
          />
          
          {/* Search Icon */}
          <div className="absolute left-4 top-1/2 transform -translate-y-1/2 flex items-center justify-center w-6 h-6" aria-hidden="true">
            <svg
              xmlns="http://www.w3.org/2000/svg"
              viewBox="0 0 24 24"
              fill="currentColor"
              className={`w-6 h-6 transition-colors duration-300 ${
                isFocused ? 'text-[#dc2626]' : 'text-gray-500'
              }`}
            >
              <path d="M15.5 14h-.79l-.28-.27C15.41 12.59 16 11.11 16 9.5 16 5.91 13.09 3 9.5 3S3 5.91 3 9.5 5.91 16 9.5 16c1.61 0 3.09-.59 4.23-1.57l.27.28v.79l5 4.99L20.49 19l-4.99-5zm-6 0C7.01 14 5 11.99 5 9.5S7.01 5 9.5 5 14 7.01 14 9.5 11.99 14 9.5 14z" />
            </svg>
          </div>

          {/* Clear button (when there's text) */}
          {searchTerm && (
            <button
              type="button"
              onClick={handleClear}
              aria-label="Clear search"
              className="absolute right-2 top-1/2 transform -translate-y-1/2 p-2 rounded-full hover:bg-gray-100 active:bg-gray-200 transition-colors duration-200 min-h-[48px] min-w-[48px] flex items-center justify-center"
            >
              <svg
                xmlns="http://www.w3.org/2000/svg"
                viewBox="0 0 24 24"
                fill="currentColor"
                className="w-6 h-6 text-gray-500 hover:text-gray-700"
              >
                <path d="M19 6.41L17.59 5 12 10.59 6.41 5 5 6.41 10.59 12 5 17.59 6.41 19 12 13.41 17.59 19 19 17.59 13.41 12z" />
              </svg>
            </button>
          )}
        </div>
        
        {/* Screen reader only description */}
        <div id="search-description" className="sr-only">
          Search for restaurants, food items, and brands
        </div>
      </form>
    </div>
  );
};

export default SearchBar; 