import React from 'react';
import { useNavigate } from 'react-router-dom';
import { PromotionPopupData } from '../types/promotion';
import { dismissPromotionPopup } from '../utils/promotionUtils';
import { getTranslation } from '../config/translations';

interface PromotionPopupProps {
  promotion: PromotionPopupData;
  isVisible: boolean;
  onClose: () => void;
}

// 커스텀 기프트 아이콘
const GiftIcon: React.FC<{ className?: string }> = ({ className = "" }) => (
  <svg
    className={className}
    viewBox="0 0 24 24"
    fill="currentColor"
    width="24"
    height="24"
  >
    <path d="M20 6h-2.18c.11-.31.18-.65.18-1a2.996 2.996 0 0 0-5.5-1.65l-.5.67-.5-.68C10.96 2.54 10.05 2 9 2 7.34 2 6 3.34 6 5c0 .35.07.69.18 1H4c-1.11 0-2 .89-2 2v4c0 1.11.89 2 2 2h1v6c0 1.11.89 2 2 2h10c1.11 0 2-.89 2-2v-6h1c1.11 0 2-.89 2-2V8c0-1.11-.89-2-2-2zM9 4c.55 0 1 .45 1 1s-.45 1-1 1-1-.45-1-1 .45-1 1-1zm6 0c.55 0 1 .45 1 1s-.45 1-1 1-1-.45-1-1 .45-1 1-1zM4 8h5.5v4H4V8zm7.5 12h-4v-6h4v6zm0-8h-4V8h4v4zm4 8h-4v-6h4v6zM20 12h-5.5V8H20v4z"/>
  </svg>
);

// 커스텀 닫기 아이콘
const CloseIcon: React.FC<{ className?: string }> = ({ className = "" }) => (
  <svg
    className={className}
    viewBox="0 0 24 24"
    fill="currentColor"
    width="20"
    height="20"
  >
    <path d="M19 6.41L17.59 5 12 10.59 6.41 5 5 6.41 10.59 12 5 17.59 6.41 19 12 13.41 17.59 19 19 17.59 13.41 12 19 6.41z"/>
  </svg>
);

const PromotionPopup: React.FC<PromotionPopupProps> = ({ promotion, isVisible, onClose }) => {
  const navigate = useNavigate();

  const handleClose = () => {
    onClose();
  };

  const handleDismissForever = () => {
    dismissPromotionPopup(promotion.code);
    onClose();
  };

  const handleGetPromoCode = () => {
    // 프로모션 코드 페이지로 이동 (프로모션 데이터를 state로 전달)
    navigate('/promotion-code', {
      state: {
        promotionData: promotion
      }
    });
    handleClose();
  };

  if (!isVisible) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50 p-4">
      <div className="relative bg-white rounded-2xl shadow-2xl max-w-sm w-full mx-4 p-6 text-center animate-fade-in">
        {/* 닫기 버튼 */}
        <button
          onClick={handleClose}
          className="absolute top-4 right-4 text-gray-400 hover:text-gray-600 transition-colors"
          aria-label="Close popup"
        >
          <CloseIcon />
        </button>

        {/* 기프트 아이콘 */}
        <div className="mb-4">
          <div className="inline-flex items-center justify-center w-16 h-16 bg-gradient-to-br from-red-400 to-red-600 rounded-full shadow-lg">
            <GiftIcon className="text-white w-8 h-8" />
          </div>
        </div>

        {/* 타이틀 */}
        <h2 className="text-gray-700 text-lg font-medium mb-2">
          {getTranslation('promotion.popup.title')}
        </h2>

        {/* 할인 정보 */}
        <div className="mb-6">
          <div className="text-2xl font-bold mb-1">
            <span className="text-red-500">{promotion.discountText}</span>
            <span className="text-gray-800 ml-1">
              {getTranslation('promotion.popup.deliveryFee')}
            </span>
          </div>
          <div className="text-gray-600 text-sm">
            {getTranslation('promotion.popup.validUntil')} <span className="text-red-500 font-medium">{promotion.validUntilText}</span>
          </div>
        </div>

        {/* 프로모션 코드 버튼 */}
        <button
          onClick={handleGetPromoCode}
          className="w-full bg-red-500 hover:bg-red-600 text-white font-semibold py-3 px-6 rounded-lg transition-colors shadow-lg mb-3"
        >
          {getTranslation('promotion.popup.getPromoCode')}
        </button>

        {/* 그만 볼래요 버튼 */}
        <button
          onClick={handleDismissForever}
          className="text-gray-400 hover:text-gray-600 text-sm transition-colors"
        >
          {getTranslation('promotion.popup.dontShowAgain')}
        </button>
      </div>
    </div>
  );
};

export default PromotionPopup; 