import React, { useState, useEffect, useMemo } from "react";
import { useNavigate } from "react-router-dom";
import { useCart } from "../contexts/CartContext";
import BackHeader from "../components/BackHeader";
import { PayPalScriptProvider, PayPalButtons } from "@paypal/react-paypal-js";
import apiClient from "../api/config";
import {
  SupportedCurrency,
  formatPrice as formatPriceWithCurrency,
  EXCHANGE_RATES,
  getCurrencyFromLanguage,
  getCurrencyForCart,
  convertCurrency,
} from "../utils/currencyUtils";
import { getCurrentLanguage, SupportedLanguage, LANGUAGE_CHANGE_EVENT } from '../config/languageConfig';
import useTranslation from '../hooks/useTranslation';
import { useAddress } from "../contexts/AddressContext";
import { CartResponse, calculateOrder, calculateOrderGift, transformCartToCalculateRequest, transformCartToCalculateGiftRequest, CalculateOrderResponse } from "../api/cartService";

const CheckoutPage: React.FC = () => {
  const navigate = useNavigate();
  const { cart, fetchOrderId } = useCart();
  const { address } = useAddress();
  const { t } = useTranslation();

  // Get currency from URL parameters
  const location = window.location;
  const urlParams = new URLSearchParams(location.search);
  const currencyParam = urlParams.get("currency");

  // Email state management
  const [email, setEmail] = useState("");
  const [emailValid, setEmailValid] = useState(false);

  // Delivery request state management
  const [deliveryRequest, setDeliveryRequest] = useState<string | null>(null);

  // Terms expansion state
  const [termsExpanded, setTermsExpanded] = useState(false);

  // Payment processing state
  const [isProcessing, setIsProcessing] = useState(false);
  const [paymentError, setPaymentError] = useState<string | null>(null);
  
  // OrderId 상태
  const [cartOrderId, setCartOrderId] = useState<string | null>(null);
  
  // CartResponse 데이터 상태
  const [cartResponse, setCartResponse] = useState<CartResponse | null>(null);

  // 주문 금액 계산 상태 추가
  const [orderCalculation, setOrderCalculation] = useState<CalculateOrderResponse | null>(null);
  const [isCalculating, setIsCalculating] = useState<boolean>(false);

  // 현재 언어 가져오기
  const [currentLanguage, setCurrentLanguage] = useState<SupportedLanguage>(getCurrentLanguage());

  // Currency selection state - use URL parameter if available, else based on current language
  const [selectedCurrency, setSelectedCurrency] = useState<SupportedCurrency>(
    (currencyParam as SupportedCurrency) || getCurrencyForCart(currentLanguage),
  );

  // 기프트샵 여부 확인
  const isGiftShop = useMemo(() => {
    return cart?.restaurantId === 'gift-shop-1';
  }, [cart?.restaurantId]);

  // 언어 변경 감지 및 업데이트
  useEffect(() => {
    const handleLanguageChange = (event: Event) => {
      const customEvent = event as CustomEvent;
      if (customEvent.detail && customEvent.detail.language) {
        const newLanguage = customEvent.detail.language as SupportedLanguage;
        setCurrentLanguage(newLanguage);
        // URL에서 통화를 지정하지 않은 경우 언어에 따라 통화 업데이트
        if (!currencyParam) {
          setSelectedCurrency(getCurrencyForCart(newLanguage));
        }
        
        // 언어가 변경되면 cart 정보를 새로운 언어로 다시 조회
        setCartOrderId(null);
        setCartResponse(null);
        setOrderCalculation(null);
      }
    };

    window.addEventListener(LANGUAGE_CHANGE_EVENT, handleLanguageChange);
    return () => {
      window.removeEventListener(LANGUAGE_CHANGE_EVENT, handleLanguageChange);
    };
  }, [currencyParam]);

  // 주문 금액 계산 API 호출 - currentLanguage 의존성 제거
  useEffect(() => {
    const calculateOrderAmount = async () => {
      if (!cart || !cart.items.length || !address?.addressId) {
        return;
      }

      try {
        setIsCalculating(true);
        // 기프트샵 여부에 따라 다른 변환 함수와 API 호출
        const calculation = isGiftShop 
          ? await calculateOrderGift(transformCartToCalculateGiftRequest(
              cart, 
              address.addressId, 
              currentLanguage.toUpperCase()
            ), localStorage.getItem('promotionUserId') || undefined)
          : await calculateOrder(transformCartToCalculateRequest(
              cart, 
              address.addressId, 
              currentLanguage.toUpperCase()
            ), localStorage.getItem('promotionUserId') || undefined);
        
        setOrderCalculation(calculation);
        
      } catch (error) {
        console.error('[CheckoutPage] 주문 금액 계산 실패:', error);
        setPaymentError("주문 금액 계산에 실패했습니다.");
      } finally {
        setIsCalculating(false);
      }
    };

    calculateOrderAmount();
  }, [cart, address?.addressId, isGiftShop]); // currentLanguage 의존성 제거

  // 주소가 있을 때 orderId 가져오기 - currentLanguage 의존성 제거하고 cartOrderId 상태 기반으로 실행
  useEffect(() => {
    const getOrderId = async () => {
      if (cart && address?.addressId && !cartOrderId) {
        try {
          const cartResponseData = await fetchOrderId(address.addressId);
          if (cartResponseData && cartResponseData.orderId) {
            setCartOrderId(cartResponseData.orderId);
            setCartResponse(cartResponseData);
          }
        } catch (error) {
          console.error("Error fetching order ID:", error);
        }
      }
    };

    getOrderId();
  }, [cart, address?.addressId, cartOrderId, fetchOrderId]); // currentLanguage 제거, cartOrderId 추가

  // PayPal initial options
  const getPayPalClientId = () => {
    // 환경변수에서 Client ID 가져오기
    if (process.env.REACT_APP_PAYPAL_CLIENT_ID) {
      return process.env.REACT_APP_PAYPAL_CLIENT_ID;
    }

    // GitHub Pages 환경 감지
    const isGitHubPages =
      typeof window !== "undefined" &&
      window.location.hostname.includes("github.io");

    // 환경에 따른 Client ID 설정
    return isGitHubPages
      ? "Af62TVjm80kRjCCyhj-EUa-fUjLoyWc8lbYyTvrVH8qdRetwc2Dk9sT4gxvCrKFBONJMB1fHnJYW0nYg" // 운영용
      : "AWiQrkfr-umMAIIyeiLWY_Dgx3PMSazp9iUDofAQeNeIUnZo8sZuzDZPCdHJEqM9BYIE99g8DgzLI7a6"; // 개발용
  };

  // Get PayPal supported currencies
  const getSupportedPayPalCurrencies = (): SupportedCurrency[] => {
    return ["USD", "JPY", "CNY", "TWD"];
  };

  const paypalOptions = {
    clientId: getPayPalClientId(),
    currency: selectedCurrency,
    intent: "capture",
    locale: "en_US",
  };

  // Subtotal (cart items total) - API 응답값만 사용
  const subtotal = useMemo(() => {
    if (!orderCalculation) return 0;
    
    // 중국어 사용자의 경우 CNY 소계를 USD로 변환
    if (currentLanguage === 'zh-CN') {
      return convertCurrency(orderCalculation.subtotalCny, 'CNY', 'USD');
    }
    
    // 소계는 프로모션 영향을 받지 않음 (배달비 프로모션)
    switch(selectedCurrency) {
      case 'USD': return orderCalculation.subtotalUsd;
      case 'JPY': return orderCalculation.subtotalJpy;
      case 'CNY': return orderCalculation.subtotalCny;
      case 'TWD': return orderCalculation.subtotalTwd;
      case 'KRW':
      default: return orderCalculation.subtotalKrw;
    }
  }, [orderCalculation, selectedCurrency, currentLanguage]);

  // 프로모션 활성화 여부 확인
  const isPromotionActive = useMemo(() => {
    if (!orderCalculation) return false;
    
    // 중국어 사용자의 경우 CNY 프로모션 필드 확인 (USD 표기이지만)
    if (currentLanguage === 'zh-CN') {
      return orderCalculation.isPromotionCny;
    }
    
    switch(selectedCurrency) {
      case 'USD': return orderCalculation.isPromotionUsd;
      case 'JPY': return orderCalculation.isPromotionJpy;
      case 'CNY': return orderCalculation.isPromotionCny;
      case 'TWD': return orderCalculation.isPromotionTwd;
      case 'KRW':
      default: return false; // KRW는 프로모션 필드가 없으므로 false
    }
  }, [orderCalculation, selectedCurrency, currentLanguage]);
                       
  // 배송비 - API 응답값만 사용
  const DELIVERY_FEE = useMemo(() => {
    if (!orderCalculation) return 0;
    
    // 프로모션 활성화 여부에 따라 할인된 배송비 또는 원래 배송비 반환
    if (isPromotionActive) {
      // 중국어 사용자의 경우 CNY 프로모션 배송비를 USD로 변환
      if (currentLanguage === 'zh-CN') {
        return convertCurrency(orderCalculation.promotionDeliveriesCny, 'CNY', 'USD');
      }
      
      switch(selectedCurrency) {
        case 'USD': return orderCalculation.promotionDeliveriesUsd;
        case 'JPY': return orderCalculation.promotionDeliveriesJpy;
        case 'CNY': return orderCalculation.promotionDeliveriesCny;
        case 'TWD': return orderCalculation.promotionDeliveriesTwd;
        case 'KRW':
        default: return orderCalculation.deliveryFeeKrw; // KRW는 프로모션 배달비 필드가 없으므로 원래 배달비 사용
      }
    } else {
      // 프로모션이 비활성화된 경우 원래 배송비
      // 중국어 사용자의 경우 CNY 배송비를 USD로 변환
      if (currentLanguage === 'zh-CN') {
        return convertCurrency(orderCalculation.deliveryFeeCny, 'CNY', 'USD');
      }
      
      switch(selectedCurrency) {
        case 'USD': return orderCalculation.deliveryFeeUsd;
        case 'JPY': return orderCalculation.deliveryFeeJpy;
        case 'CNY': return orderCalculation.deliveryFeeCny;
        case 'TWD': return orderCalculation.deliveryFeeTwd;
        case 'KRW':
        default: return orderCalculation.deliveryFeeKrw;
      }
    }
  }, [orderCalculation, selectedCurrency, isPromotionActive, currentLanguage]);

  // 원래 배달비 (프로모션 적용 전)
  const originalDeliveryFee = useMemo(() => {
    if (!orderCalculation) return 0;
    
    // 중국어 사용자의 경우 CNY 배송비를 USD로 변환
    if (currentLanguage === 'zh-CN') {
      return convertCurrency(orderCalculation.deliveryFeeCny, 'CNY', 'USD');
    }
    
    switch(selectedCurrency) {
      case 'USD': return orderCalculation.deliveryFeeUsd;
      case 'JPY': return orderCalculation.deliveryFeeJpy;
      case 'CNY': return orderCalculation.deliveryFeeCny;
      case 'TWD': return orderCalculation.deliveryFeeTwd;
      case 'KRW':
      default: return orderCalculation.deliveryFeeKrw;
    }
  }, [orderCalculation, selectedCurrency, currentLanguage]);

  // 프로모션 할인율 계산 (배달비 기준)
  const promotionDiscountRate = useMemo(() => {
    if (!orderCalculation || !isPromotionActive) return 0;
    
    const promotionRatio = orderCalculation.promotionRatio || 0;
    return Math.round(promotionRatio * 100); // 백분율로 변환
  }, [orderCalculation, isPromotionActive]);

  // Total order amount - API 응답값만 사용
  const total = useMemo(() => {
    if (!orderCalculation) return 0;
    
    // 프로모션 활성화 여부 확인 및 프로모션 총액 사용
    if (isPromotionActive) {
      // 중국어 사용자의 경우 CNY 프로모션 총액을 USD로 변환
      if (currentLanguage === 'zh-CN') {
        return convertCurrency(orderCalculation.promotionTotalPriceCny, 'CNY', 'USD');
      }
      
      switch(selectedCurrency) {
        case 'USD': return orderCalculation.promotionTotalPriceUsd;
        case 'JPY': return orderCalculation.promotionTotalPriceJpy;
        case 'CNY': return orderCalculation.promotionTotalPriceCny;
        case 'TWD': return orderCalculation.promotionTotalPriceTwd;
        case 'KRW':
        default: return orderCalculation.totalPriceKrw; // KRW는 프로모션 총액 필드가 없으므로 원래 총액 사용
      }
    } else {
      // 프로모션이 비활성화된 경우 원래 총액
      // 중국어 사용자의 경우 CNY 총액을 USD로 변환
      if (currentLanguage === 'zh-CN') {
        return convertCurrency(orderCalculation.totalPriceCny, 'CNY', 'USD');
      }
      
      switch(selectedCurrency) {
        case 'USD': return orderCalculation.totalPriceUsd;
        case 'JPY': return orderCalculation.totalPriceJpy;
        case 'CNY': return orderCalculation.totalPriceCny;
        case 'TWD': return orderCalculation.totalPriceTwd;
        case 'KRW':
        default: return orderCalculation.totalPriceKrw;
      }
    }
  }, [orderCalculation, selectedCurrency, isPromotionActive, currentLanguage]);

  // Price formatting with selected currency - 통화별 소수점 처리 조정
  const formatPrice = (price: number) => {
    // 통화별 적절한 소수점 처리
    switch(selectedCurrency) {
      case 'USD':
        return `$${price.toFixed(2)}`;
      case 'JPY':
        return `¥${Math.round(price)}`;
      case 'KRW':
        return `₩${Math.round(price).toLocaleString()}`;
      case 'CNY':
        return `¥${price.toFixed(1)}`;
      case 'TWD':
        return `NT$${Math.round(price)}`;
      default:
        return formatPriceWithCurrency(price, selectedCurrency);
    }
  };

  // Email validation
  const validateEmail = (email: string) => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  };

  // Email input change handler
  const handleEmailChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newEmail = e.target.value;
    setEmail(newEmail);
    setEmailValid(validateEmail(newEmail));
  };

  // Currency selection handler
  const handleCurrencyChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    setSelectedCurrency(e.target.value as SupportedCurrency);
  };

  // Delivery request change handler
  const handleDeliveryRequestChange = (request: string) => {
    setDeliveryRequest(request === deliveryRequest ? null : request);
  };

  // Create PayPal order
  const createOrder = (data: any, actions: any) => {
    if (!emailValid || !cart || !orderCalculation) {
      return Promise.reject(new Error("Required data not available"));
    }

    // items 배열 생성 및 실제 item_total 계산
    const paypalItems = cart.items.map((item) => {
      // 현재 통화에 맞는 가격 필드 선택
      const priceField = `price${selectedCurrency.charAt(0).toUpperCase() + selectedCurrency.slice(1).toLowerCase()}` as keyof typeof item;
      // 해당 통화 가격이 있으면 사용, 없으면 기본 가격 사용
      const itemPrice = item[priceField] !== undefined ? Number(item[priceField]) : item.price;
      
      return {
        name: item.name,
        unit_amount: {
          currency_code: selectedCurrency,
          value: itemPrice.toFixed(2),
        },
        quantity: item.quantity,
      };
    });

    // PayPal items 배열의 실제 합계 계산
    const calculatedItemTotal = paypalItems.reduce((sum, item) => {
      return sum + (parseFloat(item.unit_amount.value) * item.quantity);
    }, 0);

    // 정확한 total 계산
    const calculatedTotal = calculatedItemTotal + DELIVERY_FEE;

    return actions.order.create({
      purchase_units: [
        {
          description: `Order from ${cart.restaurantName}`,
          amount: {
            currency_code: selectedCurrency,
            value: calculatedTotal.toFixed(2),
            breakdown: {
              item_total: {
                currency_code: selectedCurrency,
                value: calculatedItemTotal.toFixed(2),
              },
              shipping: {
                currency_code: selectedCurrency,
                value: DELIVERY_FEE.toFixed(2),
              },
            },
          },
          items: paypalItems,
        },
      ],
      application_context: {
        shipping_preference: "NO_SHIPPING",
      },
    });
  };

  // PayPal payment approval handler
  const onApprove = async (data: any, actions: any) => {
    if (!cart) return;

    setIsProcessing(true);
    setPaymentError(null);

    try {
      const orderDetails = await actions.order.capture();

      // Get orderId from cart or from the API call
      const orderId = cartOrderId || cart.orderId;
      
      if (!orderId) {
        throw new Error("Order ID not found. Please try again.");
      }

      // PayPal order ID를 payment ID로 사용
      const paymentId = data.orderID;

      // Extract PayPal transaction ID
      const transactionId =
        orderDetails.purchase_units[0]?.payments?.captures[0]?.id || "";

      // Prepare backend API request body - 백엔드가 기대하는 단순한 형식으로 수정
      const requestBody = {
        paypalOrderId: paymentId,
        email: email
      };

      let apiSuccess = false;
      let retryCount = 0;
      const MAX_RETRIES = 1;

      while (!apiSuccess && retryCount <= MAX_RETRIES) {
        try {
          // Call backend API using apiClient
          const response = await apiClient.post(
            `/api/orders/${orderId}/payment`,
            requestBody
          );

          if (response.status >= 200 && response.status < 300) {
            apiSuccess = true;

            // 프로모션이 활성화되어 있으면 프로모션 사용 API 호출
            if (isPromotionActive) {
              const promotionUserId = localStorage.getItem('promotionUserId');
              if (promotionUserId) {
                try {
                  // benefit 값 계산 (원래 배달비 - 할인된 배송비 = 할인 금액)
                  const benefitAmount = originalDeliveryFee - DELIVERY_FEE;
                  
                  const promotionRequestBody = {
                    benefit: benefitAmount.toString()
                  };

                  await apiClient.put(
                    `/api/v1/promotions/users/${promotionUserId}/use`,
                    promotionRequestBody,
                    {
                      headers: {
                        'X-SERVER-AUTH': 'secret'
                      }
                    }
                  );
                } catch (promotionError) {
                  // 프로모션 API 실패는 사용자에게 노출하지 않고 콘솔에만 로그
                  console.error('Promotion API call failed:', promotionError);
                }
              }
            }

            // Navigate to success page
            navigate("/order-success", {
              state: {
                orderId: orderId,
                paymentId: paymentId,
                currency: selectedCurrency,
              },
            });
          } else {
            console.error(`API call failed (attempt ${retryCount + 1}):`, response.statusText);
            retryCount++;
            if (retryCount <= MAX_RETRIES) {
            }
          }
        } catch (error) {
          console.error(`API error (attempt ${retryCount + 1}):`, error);
          retryCount++;
          if (retryCount <= MAX_RETRIES) {
          }
        }
      }

      // 모든 시도 후에도 실패한 경우
      if (!apiSuccess) {
        // 실패한 주문 정보를 슬랙으로 전송 - 운영 서버 API 활용
        try {
          await apiClient.post(
            "https://api.brainbackdoor.com/api/notifications/slack/test/order",
            {
              message: `결제 API 호출 실패. orderId: ${orderId}, paymentId: ${paymentId}, 금액: ${formatPrice(total)}, 이메일: ${email}, 시각: ${new Date().toISOString()}`
            }
          );
        } catch (slackError) {
          console.error("Failed to send error notification:", slackError);
        }

        // 사용자에게 오류 메시지 표시
        setPaymentError(
          t('checkout.paymentProcessing')
        );
      }
    } catch (error) {
      console.error("PayPal payment error:", error);
      setPaymentError(
        "An error occurred during payment processing. Please try again."
      );
    } finally {
      setIsProcessing(false);
    }
  };

  // Redirect to cart if cart is empty
  if (!cart || cart.items.length === 0) {
    navigate("/cart");
    return null;
  }

  // 계산 중일 때 로딩 표시
  if (isCalculating || !orderCalculation) {
    return (
      <div className="min-h-screen bg-gray-50">
        <BackHeader title={t('cart.checkout') || "Checkout"} />
        <main className="px-4 py-4 pb-32">
          <div className="animate-pulse">
            <div className="h-6 bg-gray-200 rounded mb-4"></div>
            <div className="bg-gray-100 rounded-lg p-4 mb-4">
              <div className="h-4 bg-gray-200 rounded mb-3"></div>
              <div className="space-y-3">
                <div className="h-4 bg-gray-200 rounded"></div>
                <div className="h-4 bg-gray-200 rounded"></div>
              </div>
            </div>
            <div className="bg-gray-100 rounded-lg p-4 mb-6">
              <div className="space-y-3">
                <div className="h-4 bg-gray-200 rounded"></div>
                <div className="h-4 bg-gray-200 rounded"></div>
                <div className="h-4 bg-gray-200 rounded"></div>
              </div>
            </div>
          </div>
        </main>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50">
      <BackHeader title={t('cart.checkout') || "Checkout"} />

      <main className="px-4 py-4 pb-32">
        <h1 className="text-xl font-bold text-gray-800 mb-4 text-left">
          {t('cart.orderSummary')}
        </h1>

        {/* Order information section */}
        <div className="bg-gray-100 rounded-lg p-4 mb-4">
          {/* Restaurant information */}
          <h2 className="text-base text-gray-500 mb-3 text-left">
            {/* 레스토랑 이름도 다국어 지원 */}
            {(() => {
              // 현재 언어에 맞는 레스토랑 이름 필드
              const restaurantNameField = `restaurantName${currentLanguage === 'en' ? 'En' : 
                                         currentLanguage === 'ja' ? 'Ja' : 
                                         currentLanguage === 'zh-CN' ? 'ZhCn' : 
                                         currentLanguage === 'zh-TW' ? 'ZhTw' : ''}` as keyof typeof cart;
              
              // 현재 언어에 맞는 이름이 있으면 사용
              if (cart[restaurantNameField] !== undefined) {
                return String(cart[restaurantNameField]);
              }
              
              // 영문 이름이 있으면 사용
              if (cart.restaurantNameEn !== undefined) {
                return String(cart.restaurantNameEn);
              }
              
              // 기본 이름 사용
              return cart.restaurantName;
            })()}
          </h2>

          {/* Menu list */}
          <div className="space-y-3 mb-2">
            {cart.items.map((item) => (
              <div key={item.id} className="flex justify-between">
                <div className="flex-1 flex flex-col">
                  <div className="flex items-start">
                    <span className="text-gray-600 mr-2">{item.quantity}×</span>
                    <span className="text-gray-800">
                      {/* 현재 언어에 맞는 이름 필드가 있다면 사용, 없으면 기본 이름 사용 */}
                      {(() => {
                        // 나중에 다국어 이름 필드가 추가되면 적용할 수 있도록 구조 작성
                        const nameField = `name${currentLanguage === 'en' ? 'En' : 
                                           currentLanguage === 'ja' ? 'Ja' : 
                                           currentLanguage === 'zh-CN' ? 'ZhCn' : 
                                           currentLanguage === 'zh-TW' ? 'ZhTw' : ''}` as keyof typeof item;
                        
                        return item[nameField] !== undefined ? String(item[nameField]) : item.name;
                      })()}
                    </span>
                  </div>
                  {/* 옵션 아이템 정보 추가 */}
                  {item.options.length > 0 &&
                    item.options.some((opt) => opt.optionItems.length > 0) && (
                      <div className="ml-6 mt-1 text-xs text-gray-500 text-left">
                        {item.options
                          .filter((option) => option.optionItems.length > 0)
                          .flatMap((option) => option.optionItems)
                          .map((optItem, index, allOptionItems) => (
                            <span key={optItem.id} className="inline">
                              {optItem.name}
                              {index < allOptionItems.length - 1 ? ", " : ""}
                            </span>
                          ))}
                      </div>
                    )}
                </div>
                <span className="text-gray-800 font-medium ml-4">
                  {formatPrice(
                    (() => {
                      // 현재 통화에 맞는 가격 필드 선택
                      const priceField = `price${selectedCurrency.charAt(0).toUpperCase() + selectedCurrency.slice(1).toLowerCase()}` as keyof typeof item;
                      // 해당 통화 가격이 있으면 사용, 없으면 기본 가격 사용
                      const itemPrice = item[priceField] !== undefined ? Number(item[priceField]) : item.price;
                      return itemPrice * item.quantity;
                    })()
                  )}
                </span>
              </div>
            ))}
          </div>
        </div>

        {/* Payment summary information */}
        <div className="bg-gray-100 rounded-lg p-4 mb-6">
          <div className="flex justify-between items-center mb-2">
            <p className="text-gray-700">{t('cart.subtotal')}</p>
            {currentLanguage === 'zh-CN' ? (
              <div className="text-right">
                <p className="text-gray-600">
                  {formatPriceWithCurrency(convertCurrency(subtotal, 'USD', 'CNY'), 'CNY')}
                </p>
              </div>
            ) : (
              <p className="text-gray-700">{formatPrice(subtotal)}</p>
            )}
          </div>

          <div className="flex justify-between items-center mb-2">
            <p className="text-gray-700">{t('cart.deliveryFee')}</p>
            <div className="text-right">
              {isPromotionActive && (
                <p className="text-sm text-gray-400 line-through">
                  {currentLanguage === 'zh-CN' ? (
                    <div className="space-y-1">
                      <div>{formatPriceWithCurrency(convertCurrency(originalDeliveryFee, 'USD', 'CNY'), 'CNY')}</div>
                    </div>
                  ) : (
                    formatPrice(originalDeliveryFee)
                  )}
                </p>
              )}
              <div className="flex items-center justify-end space-x-2">
                {isPromotionActive && promotionDiscountRate > 0 && (
                  <span className="text-red-500 font-bold text-sm">
                    {promotionDiscountRate === 100 ? `${t('common.free')}` : `${promotionDiscountRate}%`}
                  </span>
                )}
                {currentLanguage === 'zh-CN' ? (
                  <div className="text-right">
                    <p className="font-medium text-gray-800">
                      {formatPriceWithCurrency(convertCurrency(DELIVERY_FEE, 'USD', 'CNY'), 'CNY')}
                    </p>
                  </div>
                ) : (
                  <p className="font-medium text-gray-800">
                    {formatPrice(DELIVERY_FEE)}
                  </p>
                )}
              </div>
            </div>
          </div>

          <div className="border-t border-gray-300 pt-3 flex justify-between items-center">
            <p className="font-medium text-lg text-gray-900">{t('cart.total')}</p>
            {currentLanguage === 'zh-CN' ? (
              <div className="text-right">
                <p className="text-gray-600">
                  {formatPriceWithCurrency(convertCurrency(total, 'USD', 'CNY'), 'CNY')}
                </p>
                <p className="font-semibold text-lg text-gray-900">
                  ≈ {formatPrice(total)}
                </p>
              </div>
            ) : (
              <p className="font-semibold text-lg text-gray-900">
                {formatPrice(total)}
              </p>
            )}
          </div>
        </div>

        {/* 중국어 사용자를 위한 환율 고지 */}
        {currentLanguage === 'zh-CN' && orderCalculation && (
          <div className="bg-gray-50 p-3 rounded-lg border border-gray-200 mb-6 text-center">
            <p className="text-gray-600 text-sm">
              * 汇率参考：¥1 ≈ ${orderCalculation.exchangeRateUsd && orderCalculation.exchangeRateCny ? (orderCalculation.exchangeRateUsd / orderCalculation.exchangeRateCny).toFixed(2) : '0.14'}（每日更新一次）
            </p>
          </div>
        )}

        {/* Email input section */}
        <div className="mb-6">
          <label
            htmlFor="email"
            className="block text-gray-800 font-medium mb-2 text-left"
          >
            {t('checkout.email')} <span className="text-red-500">*</span>
          </label>
          <input
            type="email"
            id="email"
            value={email}
            onChange={handleEmailChange}
            placeholder={t('checkout.enterEmail')}
            className={`w-full p-3 border rounded-lg focus:outline-none focus:ring-2 ${
              email && !emailValid
                ? "border-red-500 focus:ring-red-200"
                : "border-gray-300 focus:ring-blue-200"
            }`}
          />
          {email && !emailValid && (
            <p className="mt-1 text-sm text-red-500 text-left">
              {t('checkout.invalidEmail')}
            </p>
          )}
          <p className="mt-1 text-sm text-gray-500 text-left">
            {t('checkout.confirmationEmail')}
          </p>
        </div>

        {/* Delivery requests section */}
        <div className="mb-6">
          <h2 className="text-xl font-bold text-gray-800 mb-3 text-left">
            {t('checkout.deliveryRequests')}
          </h2>
          <div className="grid grid-cols-2 gap-3">
            <button
              type="button"
              onClick={() =>
                handleDeliveryRequestChange(t('checkout.noRingBell'))
              }
              className={`p-3 border rounded-lg text-left ${
                deliveryRequest === t('checkout.noRingBell')
                  ? "border-red-500 bg-red-50"
                  : "border-gray-300 hover:border-gray-400"
              }`}
            >
              {t('checkout.noRingBell')}
            </button>

            <button
              type="button"
              onClick={() => handleDeliveryRequestChange(t('checkout.leaveAtDoor'))}
              className={`p-3 border rounded-lg text-left ${
                deliveryRequest === t('checkout.leaveAtDoor')
                  ? "border-red-500 bg-red-50"
                  : "border-gray-300 hover:border-gray-400"
              }`}
            >
              {t('checkout.leaveAtDoor')}
            </button>

            <button
              type="button"
              onClick={() =>
                handleDeliveryRequestChange(t('checkout.callIfProblem'))
              }
              className={`p-3 border rounded-lg text-left ${
                deliveryRequest === t('checkout.callIfProblem')
                  ? "border-red-500 bg-red-50"
                  : "border-gray-300 hover:border-gray-400"
              }`}
            >
              {t('checkout.callIfProblem')}
            </button>

            <button
              type="button"
              onClick={() =>
                handleDeliveryRequestChange(t('checkout.stayingAtRoom'))
              }
              className={`p-3 border rounded-lg text-left ${
                deliveryRequest === t('checkout.stayingAtRoom')
                  ? "border-red-500 bg-red-50"
                  : "border-gray-300 hover:border-gray-400"
              }`}
            >
              {t('checkout.stayingAtRoom')}
            </button>

            <button
              type="button"
              onClick={() => handleDeliveryRequestChange(t('checkout.addUtensils'))}
              className={`p-3 border rounded-lg text-left ${
                deliveryRequest === t('checkout.addUtensils')
                  ? "border-red-500 bg-red-50"
                  : "border-gray-300 hover:border-gray-400"
              }`}
            >
              {t('checkout.addUtensils')}
            </button>
          </div>
        </div>

        {/* Payment method section */}
        <div className="mb-6">
          <h2 className="text-xl font-bold text-gray-800 mb-3 text-left">
            {t('checkout.paymentMethod')}
          </h2>

          <div className="p-4 bg-gray-50 rounded-lg border border-gray-200 mb-4">
            <p className="text-gray-700">
              {t('checkout.paypalSecure')}
            </p>
            <p className="text-sm text-gray-500 mt-1">
              {t('checkout.paypalOptions')}
            </p>
            <p className="text-sm text-gray-500 mt-1">
              {t('checkout.currency')}: {selectedCurrency}
            </p>
          </div>

          {/* Display payment error if any */}
          {paymentError && (
            <div className="mt-2 p-3 bg-red-50 border border-red-200 rounded-lg text-red-700 text-sm mb-4">
              {paymentError}
            </div>
          )}

          {/* PayPal button section */}
          {emailValid ? (
            <div className="mt-4">
              <PayPalScriptProvider options={paypalOptions}>
                <PayPalButtons
                  style={{ layout: "vertical" }}
                  createOrder={createOrder}
                  onApprove={onApprove}
                  disabled={isProcessing}
                  onError={(err) => {
                    console.error("PayPal error:", err);
                    setPaymentError(
                      "An error occurred with PayPal. Please try again.",
                    );
                  }}
                />
              </PayPalScriptProvider>

              {isProcessing && (
                <div className="mt-3 text-center text-gray-600">
                  <p>Processing your payment. Please wait...</p>
                </div>
              )}
            </div>
          ) : (
            <div className="mt-4 p-4 bg-yellow-50 border border-yellow-100 rounded-lg text-center">
              <p className="text-yellow-700">
                Please enter a valid email address to access the PayPal payment
                button.
              </p>
            </div>
          )}
        </div>

        {/* Terms section */}
        <div className="mt-4 text-center text-gray-500 text-sm">
          <p className="mb-2">
            By proceeding with payment,
            <button
              type="button"
              className="text-gray-700 font-medium inline-flex items-center ml-1"
              onClick={() => setTermsExpanded(!termsExpanded)}
            >
              you agree to our Privacy Policy and Terms
              <svg
                xmlns="http://www.w3.org/2000/svg"
                viewBox="0 0 24 24"
                fill="currentColor"
                className={`w-5 h-5 ml-1 transition-transform ${termsExpanded ? "rotate-180" : ""}`}
              >
                <path d="M7 10l5 5 5-5z" />
              </svg>
            </button>
          </p>

          {termsExpanded && (
            <div className="mt-3 text-left bg-gray-50 p-4 rounded-lg border border-gray-200 text-xs leading-relaxed">
              <h3 className="font-bold mb-2 text-gray-700">
                Privacy Policy and Terms of Service
              </h3>
              <p className="mb-2">
                <strong>1. Collection of Personal Information:</strong> We
                collect personal information such as your name, email address,
                phone number, and delivery address to process your order and
                provide you with a seamless food delivery experience.
              </p>
              <p className="mb-2">
                <strong>2. Use of Information:</strong> The information we
                collect is used to process your orders, manage your account,
                provide customer support, and improve our services.
              </p>
              <p className="mb-2">
                <strong>3. Payment Information:</strong> Your payment
                information is processed securely through our payment partners.
                We do not store your full credit card details on our servers.
              </p>
              <p className="mb-2">
                <strong>4. Refund Policy:</strong> Refunds are processed
                according to our refund policy, which may vary depending on the
                restaurant and the circumstances of the refund request.
              </p>
              <p className="mb-2">
                <strong>5. Delivery Terms:</strong> Delivery times are estimates
                and may vary depending on factors such as traffic, weather
                conditions, and restaurant preparation times.
              </p>
              <p className="mb-2">
                <strong>6. Multiple Currencies:</strong> While we display prices
                in multiple currencies for your convenience, the final charges
                may be subject to exchange rates at the time of processing.
              </p>
              <p>
                By proceeding with payment, you acknowledge that you have read
                and agree to these terms and conditions.
              </p>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

export default CheckoutPage;

