import React, { useState, useEffect, useCallback, useRef } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import BackHeader from '../components/BackHeader';
import NavigationBar from '../components/NavigationBar';
import { useAddress } from '../contexts/AddressContext';
import { getCurrentPosition, reverseGeocode, getIpBasedLocation, geocodeAddressUnified } from '../services/LocationService';
import { showChannelTalk, trackChannelTalkEvent } from '../services/ChannelService';
import NaverMap from '../components/NaverMap';
import { createAddress, CreateAddressRequest, getEnhancedAddress } from '../api/addressService';
import useTranslation from '../hooks/useTranslation';
import { getCurrentLanguage } from '../config/languageConfig';
import { initNaverMaps } from '../utils/naverMapsLoader';

const AddressSetupPage: React.FC = () => {
  const navigate = useNavigate();
  const [searchParams, setSearchParams] = useSearchParams();
  const { address, setAddress } = useAddress();
  const { t } = useTranslation(); // 다국어 처리 훅 사용
  
  const [mainAddress, setMainAddress] = useState('');
  const [detailAddress, setDetailAddress] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [locationError, setLocationError] = useState<string | null>(null);
  const [touched, setTouched] = useState({
    mainAddress: false,
    detailAddress: false
  });
  const [currentLocation, setCurrentLocation] = useState<{ lat: number; lng: number } | null>(null);
  const [showMap, setShowMap] = useState(false);
  
  // 지오코딩 관련 상태 추가
  const [isGeocoding, setIsGeocoding] = useState(false);
  const [geocodingDebounceTimer, setGeocodingDebounceTimer] = useState<NodeJS.Timeout | null>(null);
  
  // 원본 주소 정보 저장 (Cancel 기능을 위해)
  const [originalAddress, setOriginalAddress] = useState({
    mainAddress: '',
    detailAddress: '',
    location: null as { lat: number; lng: number } | null
  });
  
  // 뷰/편집 모드 관련 상태
  const [isEditMode, setIsEditMode] = useState(false);
  const [showConfirmDialog, setShowConfirmDialog] = useState(false);
  
  // API 호출 완료 여부 추적 (무한 재귀 방지)
  const hasLoadedFromApiRef = useRef(false);
  
  // 편집 모드 결정 로직
  useEffect(() => {
    const mode = searchParams.get('mode');
    const hasAddress = address && address.isComplete;
    
    if (!hasAddress) {
      // 주소 정보가 없으면 항상 편집 모드
      setIsEditMode(true);
    } else {
      // 주소 정보가 있으면 URL 파라미터에 따라 결정
      setIsEditMode(mode === 'edit');
    }
  }, [address, searchParams]);
  
  // 지오코딩 처리 함수
  const handleAddressGeocode = useCallback(async (address: string) => {
    if (!address || address.length < 5) return;
    
    setIsGeocoding(true);
    try {
      const location = await geocodeAddressUnified(address);
      if (location) {
        setCurrentLocation(location);
        setShowMap(true);
      }
    } catch (error) {
      console.error('지오코딩 실패:', error);
    } finally {
      setIsGeocoding(false);
    }
  }, []);

  // 기존 주소 정보가 있으면 로드
  useEffect(() => {
    const loadAddressData = async () => {
      if (address) {
        // addressId가 있고 아직 API에서 로드하지 않았을 때만 API 호출
        if (address.addressId && !hasLoadedFromApiRef.current) {
          try {
            hasLoadedFromApiRef.current = true; // API 호출 시작 표시
            const enhancedAddress = await getEnhancedAddress(address.addressId);
            
            // API 응답으로 컨텍스트 업데이트
            setAddress({
              mainAddress: enhancedAddress.address,
              detailAddress: enhancedAddress.detailAddress,
              lat: enhancedAddress.lat,
              lng: enhancedAddress.lng,
              addressId: enhancedAddress.id,
              stay: enhancedAddress.stay,
              isComplete: true
            });
            
            // 페이지 상태도 업데이트
            setMainAddress(enhancedAddress.address);
            setDetailAddress(enhancedAddress.detailAddress);
            
            const location = { lat: enhancedAddress.lat, lng: enhancedAddress.lng };
            setCurrentLocation(location);
            setShowMap(true);
            setOriginalAddress({
              mainAddress: enhancedAddress.address,
              detailAddress: enhancedAddress.detailAddress,
              location: location
            });
            
            return; // API 호출 성공시 기존 로직 건너뛰기
          } catch (error) {
            console.error('Enhanced address 조회 실패:', error);
            hasLoadedFromApiRef.current = false; // 실패시 다시 시도할 수 있도록 리셋
            // API 호출 실패시 기존 컨텍스트 데이터로 fallback
          }
        }
        
        // 기존 로직 (API 호출 실패하거나 addressId가 없는 경우, 또는 이미 로드된 경우)
        setMainAddress(address.mainAddress || '');
        setDetailAddress(address.detailAddress || '');
        
        // lat, lng가 있는 경우에만 설정하고 지도 표시
        if (address.lat !== undefined && address.lng !== undefined) {
          const location = { lat: address.lat, lng: address.lng };
          setCurrentLocation(location);
          setShowMap(true); // 주소 정보가 있으면 지도 표시
          setOriginalAddress({
            mainAddress: address.mainAddress || '',
            detailAddress: address.detailAddress || '',
            location: location
          });
        } else {
          // 좌표가 없지만 주소가 있는 경우 지오코딩 시도
          if (address.mainAddress) {
            handleAddressGeocode(address.mainAddress);
          }
          setOriginalAddress({
            mainAddress: address.mainAddress || '',
            detailAddress: address.detailAddress || '',
            location: null
          });
        }
      }
    };
    
    loadAddressData();
  }, [address, handleAddressGeocode]);
  
  // 유효성 검사 상태와 유효성 검사 함수
  const validateMainAddress = (address: string): { isValid: boolean; message: string | null } => {
    const trimmedAddress = address.trim();
    
    // 비어 있는지 확인
    if (trimmedAddress.length === 0) {
      return { isValid: false, message: t('address.required') };
    }
    
    // 너무 짧은지 확인 (최소 8자)
    if (trimmedAddress.length < 8) {
      return { isValid: false, message: t('address.tooShort') };
    }
    
    // 숫자가 포함되어 있는지 확인 (대부분의 주소에는 숫자가 포함됨)
    if (!/\d/.test(trimmedAddress)) {
      return { isValid: false, message: t('address.missingNumber') };
    }
    
    return { isValid: true, message: null };
  };

  // 주소 검증 결과
  const mainAddressValidation = validateMainAddress(mainAddress);
  const isMainAddressValid = mainAddressValidation.isValid;
  
  // 상세 주소 유효성 검사는 단순히 비어있지 않은지만 확인
  const isDetailAddressValid = detailAddress.trim().length > 0;
  const isFormValid = isMainAddressValid && isDetailAddressValid;
  
  // 필드 변경 및 터치 상태 관리 핸들러
  const handleMainAddressChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newAddress = e.target.value;
    setMainAddress(newAddress);
    setTouched(prev => ({ ...prev, mainAddress: true }));
    
    // 기존 디바운스 타이머 클리어
    if (geocodingDebounceTimer) {
      clearTimeout(geocodingDebounceTimer);
    }
    
    // 새로운 디바운스 타이머 설정 (1초 후 지오코딩 실행)
    if (newAddress.trim().length >= 8) { // 최소 8자 이상일 때만 지오코딩 시도
      const timer = setTimeout(() => {
        handleAddressGeocode(newAddress.trim());
      }, 1000);
      setGeocodingDebounceTimer(timer);
    } else {
      // 주소가 짧으면 지도 숨기기
      setShowMap(false);
      setCurrentLocation(null);
    }
  };

  const handleDetailAddressChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setDetailAddress(e.target.value);
    setTouched(prev => ({ ...prev, detailAddress: true }));
  };

  // 컴포넌트 언마운트 시 타이머 정리
  useEffect(() => {
    return () => {
      if (geocodingDebounceTimer) {
        clearTimeout(geocodingDebounceTimer);
      }
    };
  }, [geocodingDebounceTimer]);

  // Cancel 핸들러 - 원본 상태로 복원
  const handleCancel = () => {
    // 변경사항이 있는지 확인
    const hasChanges = mainAddress !== originalAddress.mainAddress || 
                      detailAddress !== originalAddress.detailAddress;
    
    if (hasChanges && isEditMode) {
      // 편집 모드에서 변경사항이 있으면 확인 다이얼로그 표시
      setShowConfirmDialog(true);
      return;
    }
    
    // 변경사항이 없거나 뷰 모드에서는 바로 복원
    performCancel();
  };
  
  // 실제 취소 동작 수행
  const performCancel = () => {
    // 원본 주소로 복원
    setMainAddress(originalAddress.mainAddress);
    setDetailAddress(originalAddress.detailAddress);
    setCurrentLocation(originalAddress.location);
    
    // 지도 상태 설정
    setShowMap(!!originalAddress.location);
    
    // 에러 및 기타 상태 초기화
    setLocationError(null);
    setTouched({ mainAddress: false, detailAddress: false });
    
    // 디바운스 타이머 정리
    if (geocodingDebounceTimer) {
      clearTimeout(geocodingDebounceTimer);
      setGeocodingDebounceTimer(null);
    }
    
    // 편집 모드에서 뷰 모드로 전환 (URL 파라미터 제거)
    if (isEditMode && address && address.isComplete) {
      setSearchParams({});
      setIsEditMode(false);
    }
    
    setShowConfirmDialog(false);
  };
  
  // Confirm Address 핸들러 (뷰 모드)
  const handleConfirmAddress = () => {
    navigate('/');
  };
  
  // Edit Address 핸들러 (뷰 모드에서 편집 모드로 전환)
  const handleEditAddress = () => {
    setSearchParams({ mode: 'edit' });
    setIsEditMode(true);
  };
  
  // 확인 다이얼로그 취소
  const handleDialogCancel = () => {
    setShowConfirmDialog(false);
  };
  
  // 확인 다이얼로그 확인
  const handleDialogConfirm = () => {
    performCancel();
  };

  // GPS를 사용하여 현재 위치 정보 가져오기
  const handleUseGPS = async () => {
    try {
      setIsLoading(true);
      setLocationError(null);
      
      // 브라우저의 Geolocation API를 사용하여 현재 위치 좌표 가져오기
      const position = await getCurrentPosition().catch(async (error) => {
        console.error('Geolocation API 오류:', error);
        
        // Geolocation 실패 시 IP 기반 위치 정보 사용
        if ((error as GeolocationPositionError)?.code === 1) {
          // 권한 거부 시 IP 기반 위치 정보 사용
          setLocationError(t('address.gps.permissionDenied'));
          const ipLocation = await getIpBasedLocation();
          if (!ipLocation) throw error;
          return ipLocation;
        } else if ((error as GeolocationPositionError)?.code === 2) {
          // 위치 정보를 사용할 수 없는 경우
          setLocationError(t('address.gps.unavailable'));
          const ipLocation = await getIpBasedLocation();
          if (!ipLocation) throw error;
          return ipLocation;
        } else {
          throw error;
        }
      });
      
      // 위치 정보 저장
      setCurrentLocation(position);
      
      // 약간의 지연 후 지도 표시
      setTimeout(() => {
        setShowMap(true);
      }, 500);
      
      // 현재 언어 설정에 따라 영문 주소 선호 여부 결정
      const currentLang = getCurrentLanguage();
      const preferEnglish = currentLang === 'en';
      
      // 네이버 API를 우선 사용하여 좌표를 주소로 변환 (영문 필요시 구글로 번역)
      const geoAddress = await reverseGeocode(position.lng, position.lat, preferEnglish);
      
      if (geoAddress) {
        setMainAddress(geoAddress);
        setTouched(prev => ({ ...prev, mainAddress: true }));
      } else {
        // 주소 변환 실패 시 좌표 표시
        setMainAddress(`Latitude: ${position.lat.toFixed(6)}, Longitude: ${position.lng.toFixed(6)}`);
        setLocationError(t('address.gps.coordinatesOnly'));
      }
    } catch (error) {
      console.error('위치 정보 가져오기 실패:', error);
      setLocationError(t('address.gps.failed'));
    } finally {
      setIsLoading(false);
    }
  };

  // 지도에서 위치가 선택되었을 때 호출되는 핸들러
  const handleLocationSelect = async (location: { lat: number; lng: number }) => {
    setCurrentLocation(location);
    
    // 선택된 위치의 주소 변환
    try {
      // 현재 언어 설정에 따라 영문 주소 선호 여부 결정
      const currentLang = getCurrentLanguage();
      const preferEnglish = currentLang === 'en';
      
      // 네이버 API를 우선 사용하여 좌표를 주소로 변환 (영문 필요시 구글로 번역)
      const geoAddress = await reverseGeocode(location.lng, location.lat, preferEnglish);
      
      if (geoAddress) {
        setMainAddress(geoAddress);
      } else {
        const coordsText = `Latitude: ${location.lat.toFixed(5)}, Longitude: ${location.lng.toFixed(5)}`;
        setMainAddress(coordsText);
      }
      
      setTouched(prev => ({ ...prev, mainAddress: true }));
    } catch (error) {
      console.error('선택한 위치의 주소 변환 실패:', error);
      const coordsText = `Latitude: ${location.lat.toFixed(5)}, Longitude: ${location.lng.toFixed(5)}`;
      setMainAddress(coordsText);
    }
  };

  const handleSaveAddress = async () => {
    // 모든 필드를 터치된 상태로 설정 (검증 에러 표시를 위해)
    setTouched({ mainAddress: true, detailAddress: true });

    // GPS로 가져온 주소가 좌표 형식이면 저장 허용
    const isGpsCoordinates = mainAddress.includes('Latitude:') && mainAddress.includes('Longitude:');
    
    // 유효성 검사 - 폼이 유효하지 않으면 저장하지 않음
    if (!isGpsCoordinates && !isFormValid) {
      return;
    }

    // 로딩 상태 설정
    setIsLoading(true);

    try {
      // 1. 위치 정보가 있으면 API 호출하여 주소 저장
      if (currentLocation) {
        const addressRequest: CreateAddressRequest = {
          address: mainAddress.trim(),
          detail_address: detailAddress.trim(),
          lat: currentLocation.lat.toString(),
          lng: currentLocation.lng.toString()
        };

        // API 호출
        const response = await createAddress(addressRequest);

        // 주소 정보와 ID 저장
        setAddress({
          mainAddress: mainAddress.trim(),
          detailAddress: detailAddress.trim(),
          lat: currentLocation.lat,
          lng: currentLocation.lng,
          addressId: response.id,
          isComplete: true
        });
      } else {
        // 위치 정보가 없는 경우, 기존 방식으로 저장
        setAddress({
          mainAddress: mainAddress.trim(),
          detailAddress: detailAddress.trim(),
          isComplete: true
        });
      }

      // 홈으로 이동
      navigate('/');
    } catch (error) {
      console.error('Error saving address:', error);
      // 에러 발생 시 콘솔에만 로그 출력
    } finally {
      setIsLoading(false);
    }
  };

  // 채널톡 도움말 열기
  const handleOpenHelp = () => {
    // 주소 설정 페이지에서도 사용자에게 도움을 제공하기 위해 이벤트 추적 및 채널톡 표시
    // 이벤트 추적하고 강제로 채널톡을 열도록 시도
    trackChannelTalkEvent('address_help_requested', {
      mainAddress: mainAddress,
      hasDetailAddress: !!detailAddress.trim()
    });
    
    // 채널톡이 초기화된 후에만 표시 시도
    if (window.ChannelIO) {
      try {
        // 초기화되어 있지 않은 경우 일시적으로 활성화
        window.ChannelIO('boot', {
          "pluginKey": "4de468b6-e6bf-4446-a6d0-fb3ccb1132a6",
          "language": getCurrentLanguage(),
          "hideDefaultLauncher": true,
          "customLauncherSelector": "#custom-channel-button" 
        });
        
        // 약간의 지연 후 메신저 표시 시도
        setTimeout(() => {
          showChannelTalk();
        }, 500);
      } catch (error) {
        console.error('Failed to initialize ChannelTalk on help request:', error);
        
        // 채널톡 초기화 실패 시 콘솔에만 로그 출력
      }
    } else {
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col">
      {/* Header with back button */}
      <BackHeader title={t('address.setup')} />
      
      {/* Stay 정보 배너 - stay 정보가 있을 때만 표시 */}
      {address?.stay && (
        <div className="mx-4 mt-4">
          <div className="bg-green-100 border border-green-200 rounded-lg p-2 mt-3">
            <div className="flex items-center justify-center mb-1">
              <svg className="w-5 h-5 text-green-600 mr-2" fill="currentColor" viewBox="0 0 20 20">
                <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
              </svg>
              <h3 className="text-xl font-bold text-green-800 tracking-wide">
                {t('address.stay.banner.title')}
              </h3>
            </div>
            <p className="text-xs text-green-700 leading-relaxed text-center">
              {t('address.stay.banner.subtitle')}
            </p>
          </div>
        </div>
      )}
      
      <div className="flex-1 px-4 py-2 pb-48">
        {/* Main container */}
        <div className="rounded-lg border border-gray-200 p-4 mb-2 bg-white shadow-sm">
          {/* Main Address Section */}
          <div className="mb-5">
            <label htmlFor="mainAddress" className="text-base font-medium text-gray-700 flex items-center mb-2">
              {t('address.main')}
              <span className="text-red-500 ml-1">*</span>
              {isEditMode && currentLocation && !isGeocoding && mainAddress.length >= 8 && (
                <span className="ml-2 flex items-center text-green-600 text-sm">
                  <svg className="w-4 h-4 mr-1" fill="currentColor" viewBox="0 0 20 20">
                    <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                  </svg>
                  {t('address.geocoding.found')}
                </span>
              )}
              {!isEditMode && (
                <svg className="w-4 h-4 ml-2 text-gray-500" fill="currentColor" viewBox="0 0 20 20">
                  <path fillRule="evenodd" d="M5 9V7a5 5 0 0110 0v2a2 2 0 012 2v5a2 2 0 01-2 2H5a2 2 0 01-2-2v-5a2 2 0 012-2zm8-2v2H7V7a3 3 0 016 0z" clipRule="evenodd" />
                </svg>
              )}
            </label>
            
            <input
              type="text"
              id="mainAddress"
              value={mainAddress}
              onChange={handleMainAddressChange}
              readOnly={!isEditMode}
              className={`w-full border ${
                touched.mainAddress &&
                !isMainAddressValid &&
                !mainAddress.includes('Latitude:')
                  ? 'border-red-500 focus:ring-red-200'
                  : isEditMode && currentLocation && !isGeocoding && mainAddress.length >= 8
                  ? 'border-green-500 focus:ring-green-200'
                  : isEditMode
                  ? 'border-gray-300 focus:ring-blue-200'
                  : 'border-gray-200 focus:ring-gray-100'
              } ${
                isEditMode 
                  ? 'bg-white text-gray-800 cursor-text' 
                  : 'bg-gray-50 text-gray-400 cursor-default'
              } rounded-lg p-3 focus:outline-none ${
                isEditMode ? 'focus:ring-2' : 'focus:ring-0'
              } transition-all duration-200`}
              placeholder={isEditMode ? "Enter your address (e.g., 123 Main St, Seoul)" : ""}
            />
            
            {touched.mainAddress && !isMainAddressValid && !mainAddress.includes('Latitude:') && (
              <p className="text-red-500 text-sm mt-1">{mainAddressValidation.message}</p>
            )}
            
            {locationError && (
              <p className="text-amber-600 text-sm mt-1 bg-amber-50 p-2 rounded border border-amber-200">
                {locationError}
              </p>
            )}
          </div>
          
          {/* Detail Address Section */}
          <div className="mb-5">
            <label htmlFor="detailAddress" className="text-base font-medium text-gray-700 flex items-center mb-2">
              {t('address.detail')}
              <span className="text-red-500 ml-1">*</span>
              {!isEditMode && (
                <svg className="w-4 h-4 ml-2 text-gray-500" fill="currentColor" viewBox="0 0 20 20">
                  <path fillRule="evenodd" d="M5 9V7a5 5 0 0110 0v2a2 2 0 012 2v5a2 2 0 01-2 2H5a2 2 0 01-2-2v-5a2 2 0 012-2zm8-2v2H7V7a3 3 0 016 0z" clipRule="evenodd" />
                </svg>
              )}
            </label>
            
            <input
              type="text"
              id="detailAddress"
              value={detailAddress}
              onChange={handleDetailAddressChange}
              readOnly={!isEditMode}
              className={`w-full border ${
                touched.detailAddress && !isDetailAddressValid
                  ? 'border-red-500 focus:ring-red-200'
                  : isEditMode
                  ? 'border-gray-300 focus:ring-blue-200'
                  : 'border-gray-200 focus:ring-gray-100'
              } ${
                isEditMode 
                  ? 'bg-white text-gray-800 cursor-text' 
                  : 'bg-gray-50 text-gray-400 cursor-default'
              } rounded-lg p-3 focus:outline-none ${
                isEditMode ? 'focus:ring-2' : 'focus:ring-0'
              } transition-all duration-200`}
              placeholder={isEditMode ? "Enter apartment number, building name, floor, etc." : ""}
            />
            
            {touched.detailAddress && !isDetailAddressValid && (
              <p className="text-red-500 text-sm mt-1">{t('address.detailRequired')}</p>
            )}
          </div>

          {/* Use GPS Button */}
          {isEditMode && (
            <div className="mb-5">
              <button 
                type="button"
                onClick={handleUseGPS}
                disabled={isLoading}
                className={`w-full flex items-center justify-center gap-1 py-3 rounded-lg ${
                  isLoading 
                    ? 'bg-gray-200 cursor-not-allowed' 
                    : 'bg-gray-100 hover:bg-gray-200 active:bg-gray-300 cursor-pointer'
                } transition-all duration-150 ease-in-out focus:outline-none focus:ring-2 focus:ring-gray-300`}
              >
                {isLoading ? (
                  <svg className="animate-spin h-5 w-5 text-gray-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                  </svg>
                ) : (
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-gray-700" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" />
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 11a3 3 0 11-6 0 3 3 0 016 0z" />
                  </svg>
                )}
                <span className="text-gray-700">{isLoading ? 'Loading...' : t('address.useGPS')}</span>
              </button>
            </div>
          )}
        </div>

        {/* 지도 표시 */}
        {showMap && currentLocation && (
          <div className="mb-6">
            <div className="border border-gray-200 rounded-lg overflow-hidden shadow-sm">
              <NaverMap 
                initialCenter={currentLocation}
                onLocationSelect={isEditMode ? handleLocationSelect : undefined}
                height="300px"
                zoom={19}
                markerDraggable={isEditMode}
              />
            </div>
          </div>
        )}
        
        {/* 버튼 영역 - 모드에 따라 조건부 렌더링 */}
        <div className="mt-6">
          {isEditMode ? (
            // 편집 모드: Save Changes + Cancel (기존 로직 유지)
            <>
              {/* 폼이 유효하지 않을 때 표시할 메시지 */}
              {touched.mainAddress && touched.detailAddress && !isFormValid && !mainAddress.includes('Latitude:') && (
                <div className="mb-4 p-3 bg-red-50 border border-red-200 rounded-lg">
                  <p className="text-red-700 text-sm">
                    {!isMainAddressValid && mainAddressValidation.message}
                    {!isMainAddressValid && !isDetailAddressValid && ' • '}
                    {!isDetailAddressValid && t('address.detailRequired')}
                  </p>
                </div>
              )}
              
              {/* 편집 모드에서는 항상 Save Changes와 Cancel 버튼을 함께 표시 */}
              <div className="flex flex-col gap-3">
                <button
                  type="button"
                  onClick={handleSaveAddress}
                  disabled={isLoading || (!isFormValid && !mainAddress.includes('Latitude:'))}
                  className={`w-full py-3 rounded-lg font-semibold text-white ${
                    isLoading || (!isFormValid && !mainAddress.includes('Latitude:'))
                      ? 'bg-gray-400 cursor-not-allowed'
                      : 'bg-red-500 hover:bg-red-600 active:bg-red-700'
                  } transition-all duration-150 shadow-sm`}
                >
                  {t('address.saveChanges')}
                </button>
                <button
                  type="button"
                  onClick={handleCancel}
                  className="w-full py-3 rounded-lg font-semibold text-gray-700 bg-gray-200 hover:bg-gray-300 active:bg-gray-400 transition-all duration-150 shadow-sm"
                >
                  {t('common.cancel')}
                </button>
              </div>
            </>
          ) : (
            // 뷰 모드: Confirm Address + Edit Address
            <div className="flex flex-col gap-3">
              <button
                type="button"
                onClick={handleConfirmAddress}
                className="w-full py-3 rounded-lg font-semibold text-white bg-red-500 hover:bg-red-600 active:bg-red-700 transition-all duration-150 shadow-sm"
              >
                {t('address.confirm')}
              </button>
              <button
                type="button"
                onClick={handleEditAddress}
                className="w-full py-3 rounded-lg font-semibold text-gray-700 bg-gray-200 hover:bg-gray-300 active:bg-gray-400 transition-all duration-150 shadow-sm"
              >
                {t('address.edit')}
              </button>
            </div>
          )}
        </div>
        
        {/* Help link */}
        <div className="mt-4 flex justify-center">
          <button
            type="button"
            onClick={handleOpenHelp}
            className="text-gray-600 hover:text-gray-800 focus:outline-none"
          >
            {t('address.help')}
          </button>
        </div>
      </div>
      
      {/* 확인 다이얼로그 */}
      {showConfirmDialog && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-[99999] p-4">
          <div className="bg-white rounded-lg shadow-xl max-w-sm w-full">
            <div className="p-6">
              <h3 className="text-lg font-semibold text-gray-900 mb-2">
                {t('address.confirmDialog.title')}
              </h3>
              <p className="text-gray-600 mb-6">
                {t('address.confirmDialog.message')}
              </p>
              <div className="flex flex-col gap-3">
                <button
                  onClick={handleDialogConfirm}
                  className="w-full py-3 rounded-lg font-semibold text-white bg-red-500 hover:bg-red-600 active:bg-red-700 transition-all duration-150"
                >
                  {t('address.confirmDialog.confirm')}
                </button>
                <button
                  onClick={handleDialogCancel}
                  className="w-full py-3 rounded-lg font-semibold text-gray-700 bg-gray-200 hover:bg-gray-300 active:bg-gray-400 transition-all duration-150"
                >
                  {t('address.confirmDialog.cancel')}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
      {/* Navigation Bar */}
      <NavigationBar />
    </div>
  );
};

export default AddressSetupPage; 