import React, { useState, useEffect, useCallback } from 'react';
import { getCurrentLanguage, LANGUAGE_CHANGE_EVENT, SupportedLanguage } from '../config/languageConfig';
import { getTranslation } from '../config/translations';
import { useAddressAffordance } from '../contexts/AddressAffordanceContext';
import { useNavigationAffordance } from '../contexts/NavigationAffordanceContext';
import { useAddress } from '../contexts/AddressContext';
import { getPromotionCode } from '../api/promotionService';
import { PromotionCodeResponse } from '../types/promotion';

interface BottomBannerProps {
  isVisible?: boolean;
}

const BottomBanner: React.FC<BottomBannerProps> = ({ isVisible = true }) => {
  const [timeLeft, setTimeLeft] = useState<string>('');
  const [shouldShow, setShouldShow] = useState<boolean>(false);
  const [currentLang, setCurrentLang] = useState<SupportedLanguage>(getCurrentLanguage());
  const [promotionData, setPromotionData] = useState<PromotionCodeResponse | null>(null);
  
  // 어포던스 상태 감지 - 어포던스 활성화 시 배너 숨김
  const { showAddressAffordance } = useAddressAffordance();
  const { hasAnyAffordance } = useNavigationAffordance();
  const { address } = useAddress();

  // 프로모션 상태 확인
  const checkPromotionStatus = useCallback(async () => {
    try {
      const currentLang = getCurrentLanguage();
      const addressId = address?.addressId;
      const promotionUserId = localStorage.getItem('promotionUserId');
      
      const response = await getPromotionCode(currentLang, addressId, promotionUserId || undefined);
      if (response && response.isActive && response.isApplied) {
        setPromotionData(response);
        return true;
      } else {
        setPromotionData(null);
        return false;
      }
    } catch (error) {
      console.error('프로모션 상태 확인 실패:', error);
      setPromotionData(null);
      return false;
    }
  }, [address?.addressId]);

  // 프로모션 endDate까지의 시간 계산
  const calculateTimeLeft = useCallback((): { hours: number; minutes: number; formattedTime: string } => {
    if (!promotionData || !promotionData.endDate) {
      return { hours: 0, minutes: 0, formattedTime: '0시간 0분' };
    }

    const now = new Date();
    const endDate = new Date(promotionData.endDate);
    const timeDiff = endDate.getTime() - now.getTime();
    
    if (timeDiff <= 0) {
      return { hours: 0, minutes: 0, formattedTime: '0시간 0분' };
    }
    
    const hours = Math.floor(timeDiff / (1000 * 60 * 60));
    const minutes = Math.floor((timeDiff % (1000 * 60 * 60)) / (1000 * 60));
    
    return { 
      hours, 
      minutes, 
      formattedTime: `${hours}시간 ${minutes}분` 
    };
  }, [promotionData]);

  // 언어 감지 및 표시 여부 결정
  const updateLanguageAndVisibility = useCallback(async () => {
    const lang = getCurrentLanguage();
    setCurrentLang(lang);
    
    // 프로모션 상태 확인
    const hasActivePromotion = await checkPromotionStatus();
    
    // 적용된 프로모션이 있을 때만 표시 (언어 제한 제거)
    if (hasActivePromotion) {
      setShouldShow(true);
    } else {
      setShouldShow(false);
    }
  }, [checkPromotionStatus]);

  // 초기 언어 감지 및 프로모션 상태 확인
  useEffect(() => {
    updateLanguageAndVisibility();
  }, [updateLanguageAndVisibility]);

  // 프로모션 데이터가 변경될 때마다 표시 여부 업데이트
  useEffect(() => {
    if (promotionData) {
      setShouldShow(true);
    } else {
      setShouldShow(false);
    }
  }, [promotionData]);

  // 언어 변경 이벤트 감지
  useEffect(() => {
    const handleLanguageChange = () => {
      updateLanguageAndVisibility();
    };

    window.addEventListener(LANGUAGE_CHANGE_EVENT, handleLanguageChange);
    
    return () => {
      window.removeEventListener(LANGUAGE_CHANGE_EVENT, handleLanguageChange);
    };
  }, [updateLanguageAndVisibility]);

  // 타이머 업데이트 (분 단위)
  useEffect(() => {
    if (!shouldShow || !promotionData) return;

    const updateTimer = () => {
      const timeData = calculateTimeLeft();
      setTimeLeft(timeData.formattedTime);
      
      // 0에 도달하면 배너 숨김
      if (timeData.hours === 0 && timeData.minutes === 0) {
        setShouldShow(false);
      }
    };

    // 초기 업데이트
    updateTimer();

    // 1분마다 업데이트
    const interval = setInterval(updateTimer, 60000);

    return () => clearInterval(interval);
  }, [shouldShow, promotionData, calculateTimeLeft]);

  // 프로모션 상태 주기적 확인 (5분마다)
  useEffect(() => {
    const interval = setInterval(() => {
      checkPromotionStatus();
    }, 5 * 60 * 1000); // 5분마다 확인

    return () => clearInterval(interval);
  }, [checkPromotionStatus]);

  // 배너 텍스트 가져오기
  const getBannerText = () => {
    if (!promotionData) return { promotion: '', timeLeft: '' };

    const timeData = calculateTimeLeft();
    const hoursText = getTranslation('promotion.banner.hours', currentLang);
    const minutesText = getTranslation('promotion.banner.minutes', currentLang);
    
    let timeString = '';
    if (timeData.hours > 0) {
      timeString = `${timeData.hours}${hoursText} ${timeData.minutes}${minutesText}`;
    } else {
      timeString = `${timeData.minutes}${minutesText}`;
    }

    return {
      promotion: getTranslation('promotion.banner.discountApplied', currentLang),
      timeLeft: getTranslation('promotion.banner.timeLeft', currentLang).replace('{time}', timeString)
    };
  };

  // 표시 조건 확인: 적용된 프로모션이 있고, 기타 조건들이 충족되어야 함
  if (!shouldShow || !promotionData || !isVisible || showAddressAffordance || hasAnyAffordance()) {
    return null;
  }

  const bannerText = getBannerText();

  return (
    <div className="fixed bottom-[70px] left-1/2 transform -translate-x-1/2 w-full max-w-mobile z-30">
      {/* 얇은 띠 형태 배너 - 좌우 색상 분할 */}
      <div className="flex items-center w-full h-10 bg-red-500 shadow-md overflow-hidden">
        {/* 좌측: 프로모션 텍스트 (빨간 배경) */}
        <div className="flex-1 h-full flex items-center justify-start px-5">
          <span className="text-white text-sm font-medium text-center truncate">
            {bannerText.promotion}
          </span>
        </div>
        
        {/* 우측: 타이머 (순백색 배경) */}
        <div className="flex-1 h-full flex items-center justify-end px-3">
          <span className="bg-red-500 text-yellow-300 text-[12px] font-medium px-2 py-1 rounded text-center truncate flex items-center gap-1">
            {/* 회전하는 시계 아이콘 */}
            <svg 
              className="w-4 h-4 animate-spin" 
              style={{animationDuration: '2s'}}
              viewBox="0 0 24 24" 
              fill="none" 
              stroke="currentColor" 
              strokeWidth="2"
            >
              <circle cx="12" cy="12" r="10"/>
              <polyline points="12,6 12,12 16,14"/>
            </svg>
            {bannerText.timeLeft}
          </span>
        </div>
      </div>
    </div>
  );
};

export default BottomBanner; 