import apiClient from './config';

// 숙소 주소 정보 타입 정의
export interface StayAddress {
  id: string;
  address: string;
  detail_address: string;
  lat: number;
  lng: number;
  address_kr?: string;
  detail_address_kr?: string;
}

// 숙소 정보 타입 정의
export interface StayInfo {
  id: string;
  stay_name: string;
  stay_id: string;
  address_id: string;
  created_date: string;
  updated_date: string;
  address: StayAddress;
}

/**
 * 숙소 ID로 숙소 정보 조회
 * @param stayId 숙소 ID
 * @returns 숙소 정보
 */
export const getStayInfo = async (stayId: string): Promise<StayInfo> => {
  try {
    const response = await apiClient.get<StayInfo>(`/api/stays/${stayId}`);
    return response.data;
  } catch (error) {
    console.error('Failed to fetch stay info:', error);
    
    // 개발 환경에서 백엔드 서버가 없을 때 mock 데이터 반환
    if (process.env.NODE_ENV === 'development') {
      const mockStayInfo: StayInfo = {
        id: stayId,
        stay_name: 'Test Hotel',
        stay_id: stayId,
        address_id: 'mock-address-id',
        created_date: new Date().toISOString(),
        updated_date: new Date().toISOString(),
        address: {
          id: 'mock-address-id',
          address: '서울특별시 강남구 테헤란로 123',
          detail_address: '테스트 호텔 101호',
          lat: 37.5665,
          lng: 126.9780,
          address_kr: '서울특별시 강남구 테헤란로 123',
          detail_address_kr: '테스트 호텔 101호'
        }
      };
      
      // 실제 API 호출처럼 약간의 지연 추가
      await new Promise(resolve => setTimeout(resolve, 500));
      
      return mockStayInfo;
    }
    
    throw error;
  }
}; 