import React, { useCallback, useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAddress } from '../contexts/AddressContext';
import { 
  getCurrentLanguage, 
  setLanguage, 
  SupportedLanguage, 
  detectBrowserLanguage,
  isDeviceLanguage,
  isSupportedOSLanguage,
  LANGUAGE_CHANGE_EVENT
} from '../config/languageConfig';
import useTranslation from '../hooks/useTranslation';

const Header: React.FC = () => {
  const navigate = useNavigate();
  const { t } = useTranslation();
  const { address } = useAddress();
  const [currentLang, setCurrentLang] = useState<SupportedLanguage>(getCurrentLanguage());
  
  // 앱 전체 언어 변경 시 상태 업데이트
  useEffect(() => {
    const updateLangState = () => {
      setCurrentLang(getCurrentLanguage());
    };
    
    // 언어 변경 감지를 위한 이벤트 리스너
    window.addEventListener(LANGUAGE_CHANGE_EVENT, updateLangState);
    
    return () => {
      window.removeEventListener(LANGUAGE_CHANGE_EVENT, updateLangState);
    };
  }, []);

  const handleAddressClick = () => {
    // 주소 설정 페이지로 이동
    navigate('/address');
  };

  // 언어 변경 버튼 클릭 핸들러
  const handleLanguageToggle = useCallback(() => {
    // OS 언어가 지원되는 언어(일본어, 중국어 간체, 중국어 번체)인 경우:
    // - 현재 OS 언어를 사용 중이면 → 영어로 전환
    // - 영어 사용 중이면 → OS 언어로 전환
    // OS 언어가 지원되지 않는 경우:
    // - 항상 영어 사용 (버튼 클릭 시 변경 없음)
    
    const detectedLanguage = detectBrowserLanguage();
    const supportedOSLanguage = isSupportedOSLanguage(detectedLanguage);
    
    if (supportedOSLanguage) {
      // 지원되는 OS 언어인 경우, OS 언어와 영어 간 토글
      const currentIsDeviceLang = isDeviceLanguage();
      const newLang = currentIsDeviceLang ? 'en' : detectedLanguage;
      setLanguage(newLang);
    } else if (currentLang !== 'en') {
      // 지원되지 않는 OS 언어이고 현재 영어가 아니면 영어로 설정
      setLanguage('en');
    }
    
  }, [currentLang]);

  // 디바이스 언어 또는 기본값 반환 (타입 안전)
  const getDeviceLanguageOrDefault = (): SupportedLanguage => {
    const detectedLang = detectBrowserLanguage();
    return isSupportedOSLanguage(detectedLang) ? detectedLang as SupportedLanguage : 'ko';
  };

  // 언어 코드를 짧은 표시 이름으로 변환 (스위치 표시용)
  const getShortLanguageCode = (langCode: SupportedLanguage): string => {
    const shortNames: Record<SupportedLanguage, string> = {
      'en': 'EN',
      'ko': 'KO',
      'ja': 'JP',
      'zh-CN': 'CN',
      'zh-TW': 'TW'
    };
    return shortNames[langCode] || langCode;
  };

  // 언어 코드를 표시 이름으로 변환
  const getLanguageDisplayName = (langCode: SupportedLanguage): string => {
    const langNames: Record<SupportedLanguage, string> = {
      'en': 'English',
      'ko': '한국어',
      'ja': '日本語',
      'zh-CN': '简体中文',
      'zh-TW': '繁體中文'
    };
    return langNames[langCode] || langCode;
  };

  // 주소에서 핵심 지역명 추출 함수
  const extractLocationName = (fullAddress: string, language: SupportedLanguage): string => {
    if (!fullAddress) return '';
    
    const address = fullAddress.trim();
    
    switch (language) {
      case 'en':
        // 영어: Seoul, Republic of Korea 제외
        const enParts = address.split(',').map(part => part.trim());
        const filteredParts = enParts.filter(part => 
          part !== 'Seoul' && 
          part !== 'Republic of Korea' &&
          part !== ''
        );
        return filteredParts.join(', ');
      
      case 'ko':
      case 'ja':
      case 'zh-CN':
      case 'zh-TW':
      default:
        // 한국어 및 기타 언어는 그대로 표시
        return address;
    }
  };

  return (
    <div className="md-app-bar border-b md-outline sticky top-0 z-50 bg-white">
      {/* GNB 영역 */}
      <div className="md-spacing-1 flex justify-between items-center">
        {/* 위치 정보 */}
        <div 
          className="cursor-pointer py-1 flex items-center hover:bg-gray-50 rounded transition-colors flex-grow min-w-0 mr-2 max-w-[50vw]"
          onClick={handleAddressClick}
        >
          <div className="flex items-center flex-grow min-w-0 pl-2">
            {/* Map Marker Icon */}
            <div className="flex-grow min-w-0">
              <span className="md-body-small md-on-surface block truncate font-large font-bold">
                {address ? 
                  extractLocationName(address.mainAddress, currentLang) || 
                  (address.mainAddress.length > 30 ? 
                    `${address.mainAddress.substring(0, 30)}...` : 
                    address.mainAddress
                  ) : 
                  t('header.setAddress')
                }
              </span>
            </div>
          </div>
          
          {/* 아래쪽 화살표 아이콘 */}
          <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" className="w-6 h-6 md-on-surface-variant flex-shrink-0">
            <path d="M7 10l5 5 5-5z" />
          </svg>
        </div>

        {/* 언어 선택 UI */}
        <div className="flex items-center">
          {isSupportedOSLanguage(detectBrowserLanguage()) ? (
            /* 지원되는 디바이스 언어가 있는 경우: 세그먼트 컨트롤 */
            <div className="relative bg-gray-100 rounded-lg p-1 flex items-center">
              {/* 배경 슬라이더 */}
              <div 
                className={`absolute top-1 bottom-1 bg-white rounded-md shadow-sm transition-all duration-200 ease-out ${
                  currentLang === 'en' ? 'right-1 left-1/2' : 'left-1 right-1/2'
                }`}
                style={{ width: 'calc(50% - 4px)' }}
              />
              
              {/* 디바이스 언어 버튼 */}
              <button
                onClick={() => currentLang === 'en' && handleLanguageToggle()}
                className={`relative z-10 px-3 py-1.5 text-xs font-medium rounded-md transition-colors duration-200 min-w-[28px] ${
                  currentLang !== 'en' 
                    ? 'text-gray-900' 
                    : 'text-gray-500 hover:text-gray-700'
                }`}
                aria-label={`Switch to ${getLanguageDisplayName(getDeviceLanguageOrDefault())}`}
                disabled={currentLang !== 'en'}
              >
                {getShortLanguageCode(getDeviceLanguageOrDefault())}
              </button>
              
              {/* 영어 버튼 */}
              <button
                onClick={() => currentLang !== 'en' && handleLanguageToggle()}
                className={`relative z-10 px-3 py-1.5 text-xs font-medium rounded-md transition-colors duration-200 min-w-[28px] ${
                  currentLang === 'en' 
                    ? 'text-gray-900' 
                    : 'text-gray-500 hover:text-gray-700'
                }`}
                aria-label="Switch to English"
                disabled={currentLang === 'en'}
              >
                EN
              </button>
            </div>
          ) : (
            /* 지원되지 않는 디바이스 언어인 경우: 아무것도 표시하지 않음 */
            null
          )}
        </div>
      </div>
    </div>
  );
};

export default Header; 